insert into daily_workout_assignments(id,team_id,athlete_id,workout_date,scheduled_workout) values('70000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','2040-01-01','{"name":"2k"}');
