-- RLS may hide an attempted update; its persisted outcome is checked below.
select pg_temp.denied($q$insert into team_members(team_id,user_id,role,is_admin) values('10000000-0000-0000-0000-000000000003',auth.uid(),'coach',true)$q$);
select pg_temp.denied($q$insert into organization_members(org_id,user_id,role) values('20000000-0000-0000-0000-000000000001',auth.uid(),'admin')$q$);
select join_team_by_code(' first ');
