-- Legacy private fields never leak through broad roster reads.
select pg_temp.assert_true((select notes='Private legacy notes' and coach_notes='Private legacy coach notes' from athlete_private_notes where athlete_id='30000000-0000-0000-0000-000000000099'),'legacy notes preserved privately for coach');
update athletes set notes='Coach correction' where id='30000000-0000-0000-0000-000000000099';
