update athletes set notes=null where id='30000000-0000-0000-0000-000000000099';
select pg_temp.assert_true((select notes is null and coach_notes='Private legacy coach notes' from athlete_private_notes where athlete_id='30000000-0000-0000-0000-000000000099'),'explicit note clearing works');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
