-- Role-only profile claims are user editable and must confer no creation rights.
insert into user_profiles(user_id,roles) values('00000000-0000-0000-0000-000000000009',array['coach']);
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000009',false);
select pg_temp.assert_true(not can_create_coaching_space(),'self-editable profile role cannot grant creation');
-- Atomic join rolls membership back when an archived team's roster cannot reopen.
select pg_temp.denied($q$select join_team_by_code('FIRST')$q$);
select pg_temp.assert_true((select count(*)=0 from team_members where user_id=auth.uid()),'failed roster join rolls membership back');
select join_team_by_code('OTHER');
select pg_temp.assert_true((select count(*)=1 from athletes a join team_athletes t on t.athlete_id=a.id where a.user_id=auth.uid() and t.team_id='10000000-0000-0000-0000-000000000002'),'code join atomically creates linked athlete');
reset role;
set role service_role;
select set_config('request.jwt.claim.sub','',false);
select pg_temp.assert_true(not can_admin_team('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003'),'service-role can call admin authorization RPC');
select ensure_team_member_athlete_link('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000009');
reset role;
select 'team permission checks passed' as result;
